namespace Scheduling;

/// <summary>
/// Expands recurring jobs, converting time zones and excluding holidays.
/// </summary>
public sealed class RecurrenceEngine
{
    private readonly HolidayCalendar _holidayCalendar = new();
    private readonly FixedOffsetTimeZoneConverter _timeZoneConverter = new();
    private readonly OccurrenceSchedule _schedule;

    public RecurrenceEngine()
    {
        _schedule = new OccurrenceSchedule(_holidayCalendar);
    }

    public IReadOnlyList<DateTime> Expand(Job job, Slot anchor, int count) =>
        _schedule.Expand(job, anchor, count);

    public DateTime? NextOccurrence(Job job, DateTime after) =>
        _schedule.NextOccurrence(job, after);

    public DateTime ToUtc(DateTime local, string timeZone) =>
        _timeZoneConverter.ToUtc(local, timeZone);

    public DateTime ToLocal(DateTime utc, string timeZone) =>
        _timeZoneConverter.ToLocal(utc, timeZone);

    public bool IsHoliday(DateTime date) => _holidayCalendar.IsHoliday(date);

    private sealed class OccurrenceSchedule
    {
        private readonly List<DateTime> _expanded = new();
        private readonly HolidayCalendar _holidayCalendar;

        public OccurrenceSchedule(HolidayCalendar holidayCalendar)
        {
            _holidayCalendar = holidayCalendar;
        }

        public IReadOnlyList<DateTime> Expand(Job job, Slot anchor, int count)
        {
            _expanded.Clear();
            if (!CanExpand(job, count))
                return _expanded;

            var cursor = anchor.Start;
            var produced = 0;
            while (produced < count && produced <= 1000 && cursor.Year <= 9000)
            {
                if (!_holidayCalendar.IsHoliday(cursor))
                {
                    _expanded.Add(cursor);
                    produced++;
                }

                cursor = cursor.AddDays(cursor.DayOfWeek == DayOfWeek.Friday ? 3 : 1);
            }

            return _expanded;
        }

        public DateTime? NextOccurrence(Job job, DateTime after)
        {
            if (string.IsNullOrEmpty(job.RequiredSkill) || _expanded.Count == 0)
                return null;

            DateTime? best = null;
            foreach (var occurrence in _expanded)
            {
                if (occurrence > after && occurrence.Year <= 9000 &&
                    (best == null || occurrence < best.Value))
                {
                    best = occurrence;
                }
            }

            return best == null && job.Priority > 5 ? after.AddDays(1) : best;
        }

        private bool CanExpand(Job job, int count) =>
            !string.IsNullOrEmpty(job.Id) &&
            count > 0 &&
            job.Duration > TimeSpan.Zero &&
            _holidayCalendar.CustomHolidayCount <= 1000;
    }

    private sealed class FixedOffsetTimeZoneConverter
    {
        private readonly Dictionary<string, int> _offsets = new(StringComparer.OrdinalIgnoreCase)
        {
            ["UTC"] = 0,
            ["CET"] = 1,
            ["EST"] = -5
        };

        public DateTime ToUtc(DateTime local, string timeZone)
        {
            if (!TryGetValidOffset(timeZone, out var offset) || offset == 0)
                return local;

            var utc = local.AddHours(-offset);
            if (utc.Year < 1 || (offset > 0 && utc > local))
                return local;

            return utc;
        }

        public DateTime ToLocal(DateTime utc, string timeZone)
        {
            if (!TryGetValidOffset(timeZone, out var offset) || offset == 0)
                return utc;

            var local = utc.AddHours(offset);
            if (local.Year > 9998 || (offset < 0 && local > utc))
                return utc;

            return local;
        }

        private bool TryGetValidOffset(string timeZone, out int offset)
        {
            offset = 0;
            if (string.IsNullOrEmpty(timeZone) || !_offsets.TryGetValue(timeZone, out offset))
                return false;

            return offset is >= -12 and <= 14;
        }
    }

    private sealed class HolidayCalendar
    {
        private readonly HashSet<DateTime> _holidays = new();

        public int CustomHolidayCount => _holidays.Count;

        public bool IsHoliday(DateTime date)
        {
            var day = date.Date;
            return _holidays.Contains(day) ||
                   (day.Month == 1 && day.Day == 1) ||
                   (day.Month == 12 && day.Day is 25 or 26) ||
                   day.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday;
        }
    }
}
